void* worker(void* arg) {
    int id = *(int*)arg;
    return (void*)((long)id + 1);
}

// Thread Creation and Join
pthread_t t1;
int worker_id = 1;
void* result;

pthread_create(&t1, NULL, worker, &worker_id);
pthread_join(t1, &result);
// result holds 2

// Mutex (Mutual Exclusion)
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int shared_count = 0;

void safe_increment() {
    pthread_mutex_lock(&lock);
    shared_count++; // Critical section
    pthread_mutex_unlock(&lock);
}

// Condition Variable (Wait/Signal)
pthread_cond_t data_ready;
volatile int produced = 0;

void consumer_wait(pthread_mutex_t* m) {
    pthread_mutex_lock(m);
    while (produced == 0)
        pthread_cond_wait(&data_ready, m);
    pthread_mutex_unlock(m);
}

void producer_signal(pthread_mutex_t* m) {
    pthread_mutex_lock(m);
    produced = 1;
    pthread_mutex_unlock(m);
    pthread_cond_signal(&data_ready);
}
